`timescale 1ns/1ps
//======================================================================================================
// sort9_net.v - full sorting network for 9 x 8-bit values (Batcher odd-even mergesort)
//   26 comparators, logic depth 8.  Outputs the complete sorted sequence s0<=s1<=...<=s8.
//   Used by median_switch_2px: s4 = median, and min/max of the 8 neighbours are derived
//   from s0/s1/s7/s8 together with the centre value.
//   Generated by tools/gen_sort9_net.py; verified exhaustively over alphabets {0,1},{0,1,2},{0,1,2,3}
//   and 300k random 8-bit vectors.
//======================================================================================================
module sort9_net (
    input  wire [7:0] v0, v1, v2, v3, v4, v5, v6, v7, v8,
    output wire [7:0] s0, s1, s2, s3, s4, s5, s6, s7, s8
);
    wire [7:0] w0 = v0;
    wire [7:0] w1 = v1;
    wire [7:0] w2 = v2;
    wire [7:0] w3 = v3;
    wire [7:0] w4 = v4;
    wire [7:0] w5 = v5;
    wire [7:0] w6 = v6;
    wire [7:0] w7 = v7;
    wire [7:0] w8 = v8;
    wire [7:0] w9 = (w0 < w1) ? w0 : w1;  // lower
    wire [7:0] w10 = (w0 < w1) ? w1 : w0;  // upper
    wire [7:0] w11 = (w2 < w3) ? w2 : w3;  // lower
    wire [7:0] w12 = (w2 < w3) ? w3 : w2;  // upper
    wire [7:0] w13 = (w9 < w11) ? w9 : w11;  // lower
    wire [7:0] w14 = (w9 < w11) ? w11 : w9;  // upper
    wire [7:0] w15 = (w10 < w12) ? w10 : w12;  // lower
    wire [7:0] w16 = (w10 < w12) ? w12 : w10;  // upper
    wire [7:0] w17 = (w15 < w14) ? w15 : w14;  // lower
    wire [7:0] w18 = (w15 < w14) ? w14 : w15;  // upper
    wire [7:0] w19 = (w4 < w5) ? w4 : w5;  // lower
    wire [7:0] w20 = (w4 < w5) ? w5 : w4;  // upper
    wire [7:0] w21 = (w7 < w8) ? w7 : w8;  // lower
    wire [7:0] w22 = (w7 < w8) ? w8 : w7;  // upper
    wire [7:0] w23 = (w6 < w21) ? w6 : w21;  // lower
    wire [7:0] w24 = (w6 < w21) ? w21 : w6;  // upper
    wire [7:0] w25 = (w22 < w24) ? w22 : w24;  // lower
    wire [7:0] w26 = (w22 < w24) ? w24 : w22;  // upper
    wire [7:0] w27 = (w19 < w23) ? w19 : w23;  // lower
    wire [7:0] w28 = (w19 < w23) ? w23 : w19;  // upper
    wire [7:0] w29 = (w26 < w28) ? w26 : w28;  // lower
    wire [7:0] w30 = (w26 < w28) ? w28 : w26;  // upper
    wire [7:0] w31 = (w20 < w25) ? w20 : w25;  // lower
    wire [7:0] w32 = (w20 < w25) ? w25 : w20;  // upper
    wire [7:0] w33 = (w31 < w29) ? w31 : w29;  // lower
    wire [7:0] w34 = (w31 < w29) ? w29 : w31;  // upper
    wire [7:0] w35 = (w32 < w30) ? w32 : w30;  // lower
    wire [7:0] w36 = (w32 < w30) ? w30 : w32;  // upper
    wire [7:0] w37 = (w13 < w27) ? w13 : w27;  // lower
    wire [7:0] w38 = (w13 < w27) ? w27 : w13;  // upper
    wire [7:0] w39 = (w36 < w38) ? w36 : w38;  // lower
    wire [7:0] w40 = (w36 < w38) ? w38 : w36;  // upper
    wire [7:0] w41 = (w18 < w34) ? w18 : w34;  // lower
    wire [7:0] w42 = (w18 < w34) ? w34 : w18;  // upper
    wire [7:0] w43 = (w41 < w39) ? w41 : w39;  // lower
    wire [7:0] w44 = (w41 < w39) ? w39 : w41;  // upper
    wire [7:0] w45 = (w42 < w40) ? w42 : w40;  // lower
    wire [7:0] w46 = (w42 < w40) ? w40 : w42;  // upper
    wire [7:0] w47 = (w17 < w33) ? w17 : w33;  // lower
    wire [7:0] w48 = (w17 < w33) ? w33 : w17;  // upper
    wire [7:0] w49 = (w16 < w35) ? w16 : w35;  // lower
    wire [7:0] w50 = (w16 < w35) ? w35 : w16;  // upper
    wire [7:0] w51 = (w49 < w48) ? w49 : w48;  // lower
    wire [7:0] w52 = (w49 < w48) ? w48 : w49;  // upper
    wire [7:0] w53 = (w47 < w43) ? w47 : w43;  // lower
    wire [7:0] w54 = (w47 < w43) ? w43 : w47;  // upper
    wire [7:0] w55 = (w51 < w44) ? w51 : w44;  // lower
    wire [7:0] w56 = (w51 < w44) ? w44 : w51;  // upper
    wire [7:0] w57 = (w52 < w45) ? w52 : w45;  // lower
    wire [7:0] w58 = (w52 < w45) ? w45 : w52;  // upper
    wire [7:0] w59 = (w50 < w46) ? w50 : w46;  // lower
    wire [7:0] w60 = (w50 < w46) ? w46 : w50;  // upper

    assign s0 = w37;
    assign s1 = w53;
    assign s2 = w54;
    assign s3 = w55;
    assign s4 = w56;
    assign s5 = w57;
    assign s6 = w58;
    assign s7 = w59;
    assign s8 = w60;
endmodule
